<script setup>
import PublicLayout from '../../../Layouts/PublicLayout.vue';
import AdminQuickLinks from '../../../Components/AdminQuickLinks.vue';
import { useForm, usePage } from '@inertiajs/vue3';
import { ref } from 'vue';
import { Plus, Upload, Trash2, Image as ImageIcon } from 'lucide-vue-next';
const props = defineProps({ albums: { type: Array, default: () => [] } });
const page = usePage();
const albumForm = useForm({ title: '', description: '', cover_image: null, published: false });
const uploads = ref({});
const editing = ref(null);
const editForm = useForm({ title: '', description: '', cover_image: null, published: false });
const createAlbum = () => albumForm.post('/admin/gallery/albums', { forceFormData: true, onSuccess: () => albumForm.reset() });
const beginEdit = (album) => { editing.value = album.id; editForm.title = album.title; editForm.description = album.description || ''; editForm.published = album.published; editForm.cover_image = null; };
const saveEdit = (id) => editForm.post(`/admin/gallery/albums/${id}`, { forceFormData: true, onSuccess: () => editing.value = null });
const upload = (id) => { const f = useForm({ images: uploads.value[id] || [] }); f.post(`/admin/gallery/albums/${id}/images`, { forceFormData: true, onSuccess: () => uploads.value[id] = [] }); };
const removeAlbum = (id) => { if (confirm('Delete this album and all its images?')) useForm({}).delete(`/admin/gallery/albums/${id}`); };
const removeImage = (id) => { if (confirm('Delete this image?')) useForm({}).delete(`/admin/gallery/images/${id}`); };
</script>
<template><PublicLayout><section class="bg-[#00351F]"><div class="mx-auto max-w-[1400px] px-5 py-10"><p class="text-xs font-bold uppercase tracking-widest text-[#D4A72C]">Administration</p><h1 class="mt-2 text-3xl font-extrabold text-white">Gallery Management</h1><p class="mt-2 text-sm text-white/70">Create albums, upload photographs and control what appears publicly.</p></div><AdminQuickLinks /></section><section class="bg-[#F7F9F7] py-10"><div class="mx-auto max-w-[1200px] space-y-8 px-5">
<div v-if="page.props.flash?.success" class="rounded-lg bg-green-50 p-3 text-sm text-green-800">{{ page.props.flash.success }}</div>
<form @submit.prevent="createAlbum" class="rounded-2xl border bg-white p-6"><h2 class="mb-4 text-xl font-extrabold text-[#00351F]">Create album</h2><div class="grid gap-4 md:grid-cols-2"><input v-model="albumForm.title" required placeholder="Album title" class="rounded-lg border-gray-300"/><input type="file" accept="image/*" @input="albumForm.cover_image=$event.target.files[0]" class="rounded-lg border p-2"/><textarea v-model="albumForm.description" placeholder="Album description" class="rounded-lg border-gray-300 md:col-span-2"/><label class="flex items-center gap-2 text-sm"><input v-model="albumForm.published" type="checkbox"/> Publish album</label></div><button class="mt-4 inline-flex items-center gap-2 rounded-lg bg-[#006B3C] px-5 py-3 text-sm font-bold text-white"><Plus :size="16"/> CREATE ALBUM</button><p v-if="albumForm.errors.title" class="mt-2 text-xs text-red-600">{{ albumForm.errors.title }}</p></form>
<div v-for="album in albums" :key="album.id" class="rounded-2xl border bg-white p-6"><div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="text-xl font-extrabold text-[#00351F]">{{ album.title }}</h2><p class="text-xs text-gray-500">{{ album.images_count }} images · {{ album.published ? 'Published' : 'Draft' }}</p><p class="mt-2 text-sm text-gray-600">{{ album.description }}</p></div><div class="flex gap-2"><button @click="beginEdit(album)" class="rounded-lg border px-3 py-2 text-xs font-bold">EDIT</button><button @click="removeAlbum(album.id)" class="rounded-lg bg-red-50 px-3 py-2 text-xs font-bold text-red-700">DELETE</button></div></div>
<form v-if="editing===album.id" @submit.prevent="saveEdit(album.id)" class="mt-4 grid gap-3 rounded-lg bg-gray-50 p-4 md:grid-cols-2"><input v-model="editForm.title" required class="rounded-lg border-gray-300"/><input type="file" accept="image/*" @input="editForm.cover_image=$event.target.files[0]"/><textarea v-model="editForm.description" class="rounded-lg border-gray-300 md:col-span-2"/><label class="flex items-center gap-2 text-sm"><input v-model="editForm.published" type="checkbox"/> Published</label><button class="rounded-lg bg-[#006B3C] px-4 py-2 text-sm font-bold text-white">SAVE CHANGES</button></form>
<form @submit.prevent="upload(album.id)" class="mt-5 flex flex-wrap items-center gap-3 border-t pt-4"><input type="file" multiple accept="image/jpeg,image/png,image/webp" @change="uploads[album.id]=Array.from($event.target.files)"/><button class="inline-flex items-center gap-2 rounded-lg bg-[#00351F] px-4 py-2 text-xs font-bold text-white"><Upload :size="14"/> UPLOAD PHOTOS</button><span class="text-xs text-gray-500">Up to 20 images per upload; 5MB each.</span></form>
<div v-if="album.images?.length" class="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4 lg:grid-cols-6"><div v-for="photo in album.images" :key="photo.id" class="relative overflow-hidden rounded-lg"><img :src="photo.image.startsWith('http') || photo.image.startsWith('/') ? photo.image : `/storage/${photo.image}`" class="h-28 w-full object-cover"/><button @click="removeImage(photo.id)" class="absolute right-1 top-1 rounded bg-white/90 p-1 text-red-600"><Trash2 :size="14"/></button></div></div><p v-else class="mt-4 text-xs text-gray-500">No photographs in this album yet.</p></div>
<div v-if="!albums.length" class="rounded-xl bg-white p-8 text-center text-sm text-gray-500">No albums created yet.</div></div></section></PublicLayout></template>
